/**
 * Point every published article and quiz at a self-hosted cover.
 *
 * 27 of the site's 37 images were hotlinked from top4top.io, a free image
 * host. Eleven of them were already returning nothing, so roughly a third of
 * the cards on the site were showing a broken image — including on the
 * explore page, which is exactly where a reviewer looks. The remaining
 * sixteen are one outage away from the same.
 *
 * All of them now resolve to /thumbnails/*.png, generated by
 * scripts/thumbnail-studio and committed to the repo, so nothing on the page
 * depends on a third party staying up.
 *
 * Usage:
 *   node --experimental-strip-types scripts/set-thumbnails.ts [--apply]
 */

import fs from "node:fs";
import path from "node:path";
import readline from "node:readline/promises";
import { stdin, stdout } from "node:process";

import { initializeApp } from "firebase/app";
import { getAuth, signInWithEmailAndPassword } from "firebase/auth";
import { collection, doc, getDocs, getFirestore, updateDoc } from "firebase/firestore";

const APPLY = process.argv.includes("--apply");
const P = (n: string) => `/thumbnails/${n}.png`;
/**
 * The eleven photographic covers are JPEGs. The same frame is 1165 KB as a
 * PNG and under 90 KB as a JPEG, and eighteen of them load on /explore at
 * once — PNG is simply the wrong container for a photograph.
 */
const J = (n: string) => `/thumbnails/${n}.jpg`;

const ARTICLES: Record<string, string> = {
  "شخصية-قيادية": P("article-leadership"),
  "ما-هو-اختبار-الذكاء-وكيف-يقاس": P("article-iq-guide"),
  "كيف-تختار-المهنة-المناسبة-لك": P("article-career-choice"),
  "اهمية-النوم-الجيد-وتاثيره-على-الصحة": P("article-sleep"),
  "كيف-تتكون-الشخصية": P("article-personality-formation"),
  "كيف-تتعامل-مع-الحزن؟-10-طرق-فعالة-لتجاوز-المشاعر-الصعبة": P("article-grief"),
  "كيف-تتعامل-مع-الغضب": P("article-anger"),
  "القلق-اسبابه-واعراضه-وكيفية-التعامل-معه": P("article-anxiety"),
  "كيف-تتخلص-من-الشعور-بالوحدة": P("article-loneliness"),
  "-كيف-تبني-عادات-تدوم؟-دليل-عملي-من-علم-النفس": P("article-habits"),
  "-لماذا-نخاف-من-الفشل؟-وما-الذي-يمنعنا-من-المحاولة؟": P("article-fear-failure"),
  "-كيف-تتوقف-عن-التفكير-الزائد؟-دليل-عملي-لاستعادة-هدوء-عقلك": P("article-overthinking"),
  "-لماذا-يصعب-علينا-مسامحة-الآخرين؟-وهل-المسامحة-تعني-نسيان-ما-حدث؟": P("article-forgiveness"),
  "الفرق-بين-الحب-والتعلق-والاعجاب": P("article-love-attachment"),
  // November additions — regenerated in the same visual system.
  "نموذج-العوامل-الخمسة-الكبرى": J("article-big-five"),
  "انماط-التعلق-في-العلاقات": J("article-attachment"),
  "لماذا-تبدو-نتائج-اختبارات-الشخصية-دقيقة": J("article-barnum"),
  "الذكاء-العاطفي-ما-يثبته-البحث": J("article-emotional-intelligence"),
  "الاحتراق-الوظيفي-اعراضه-وكيف-تتعامل-معه": J("article-burnout"),
  "التسويف-لماذا-نؤجل-وكيف-نتوقف": J("article-procrastination"),
};

const QUIZZES: Record<string, string> = {
  "اختبار-مستوى-الذكاء": P("quiz-iq"),
  "العمر-العاطفي-لشخصيتك": P("quiz-emotional-age"),
  "هل-تعاني-من-القلق": P("quiz-anxiety"),
  "ما-لغة-الحب-الخاصة-بك": P("quiz-love-language"),
  "ما-يستنزف-طاقتك-النفسية": P("quiz-energy-drain"),
  "ما-نسبة-العناد-لديك": P("quiz-stubbornness"),
  "جاهزيتك-لسوق-العمل": P("quiz-job-readiness"),
  "مم-تتكون-شخصيتك": P("quiz-personality-parts"),
  "كم-مرة-يخدعك-عقلك": P("quiz-cognitive-bias"),
  "اللون-الذي-يكشف-اسرار-شخصيتك": P("quiz-color"),
  "هل-تصلح-لتكون-مهندسا": P("quiz-engineer"),
  "are-you-a-manager": P("quiz-manager"),
  "الحيوان-الذي-يشبه-شخصيتك": P("quiz-animal"),
  "اختبار-العوامل-الخمسة-الكبرى": J("quiz-big-five"),
  "اختبار-نمط-التعلق": J("quiz-attachment"),
  "مقياس-الاحتراق-الوظيفي": J("quiz-burnout"),
  "مستوى-التسويف-لديك": J("quiz-procrastination"),
  "اختبار-الذكاء-العاطفي": J("quiz-emotional-intelligence"),
};

function loadEnv() {
  const file = path.join(process.cwd(), ".env.local");
  if (!fs.existsSync(file)) throw new Error(".env.local not found");
  for (const line of fs.readFileSync(file, "utf8").split(/\r?\n/)) {
    const m = /^\s*([A-Z0-9_]+)\s*=\s*(.*)$/.exec(line);
    if (m && !process.env[m[1]]) process.env[m[1]] = m[2].trim().replace(/^["']|["']$/g, "");
  }
}

async function main() {
  // Refuse to point Firestore at a file that is not actually there.
  const missing = [...Object.values(ARTICLES), ...Object.values(QUIZZES)].filter(
    (p) => !fs.existsSync(path.join(process.cwd(), "public", p.replace(/^\//, ""))),
  );
  if (missing.length) {
    console.error("These files do not exist yet — run the thumbnail studio first:");
    for (const m of missing) console.error("  " + m);
    process.exit(1);
  }

  loadEnv();
  const app = initializeApp({
    apiKey: process.env.VITE_FIREBASE_API_KEY,
    authDomain: process.env.VITE_FIREBASE_AUTH_DOMAIN,
    projectId: process.env.VITE_FIREBASE_PROJECT_ID,
    storageBucket: process.env.VITE_FIREBASE_STORAGE_BUCKET,
    messagingSenderId: process.env.VITE_FIREBASE_MESSAGING_SENDER_ID,
    appId: process.env.VITE_FIREBASE_APP_ID,
  });
  let email = process.env.ADMIN_EMAIL;
  let password = process.env.ADMIN_PASSWORD;
  if (!email || !password) {
    const rl = readline.createInterface({ input: stdin, output: stdout });
    email ||= await rl.question("Admin email: ");
    password ||= await rl.question("Admin password: ");
    rl.close();
  }
  await signInWithEmailAndPassword(getAuth(app), email!, password!);
  const db = getFirestore(app);
  console.log(`Signed in as ${email}\n`);

  let changed = 0;
  let unmatched = 0;

  for (const [coll, field, map] of [
    ["articles", "image", ARTICLES],
    ["quizzes", "thumbnail", QUIZZES],
  ] as const) {
    const snap = await getDocs(collection(db, coll));
    const bySlug = new Map(
      snap.docs.map((d) => [String((d.data() as any).slug ?? "").trim(), d]),
    );
    for (const [slug, target] of Object.entries(map)) {
      const d = bySlug.get(slug);
      if (!d) {
        console.log(`MISS  ${coll}: ${slug.slice(0, 44)}`);
        unmatched++;
        continue;
      }
      const current = String((d.data() as any)[field] ?? "");
      if (current === target) continue;
      const was = current.includes("top4top") ? "top4top" : current || "(empty)";
      console.log(`${coll.padEnd(8)} ${slug.slice(0, 40).padEnd(42)} ${was.slice(0, 20)} -> ${target}`);
      if (!APPLY) continue;
      await updateDoc(doc(db, coll, d.id), {
        [field]: target,
        updatedAt: new Date().toISOString(),
      });
      changed++;
    }
  }

  console.log(
    APPLY
      ? `\nUpdated ${changed} document(s).`
      : "\nDry run — nothing written. Re-run with --apply.",
  );
  if (unmatched) console.log(`${unmatched} slug(s) not found.`);
  process.exit(unmatched ? 1 : 0);
}

main().catch((e) => {
  console.error("\nFailed:", e?.message || e);
  process.exit(1);
});
